import React, { useState } from "react";

export default function RoutePlanner({ tourist }) {
  const [destination, setDestination] = useState("");
  const [places, setPlaces] = useState([]);

  const handleAdd = () => {
    if (!destination.trim()) return;
    setPlaces([...places, destination]);
    setDestination("");
  };

  const handleStart = () => {
    alert("Your personalized route is being generated!");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background:
          "linear-gradient(135deg, #ffb347, #ff6a00), url('https://images.unsplash.com/photo-1571908599427-9a97e89ddf96?auto=format&fit=crop&w=1600&q=80')",
        backgroundSize: "cover",
        backgroundPosition: "center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255,255,255,0.9)",
          padding: "40px",
          borderRadius: "20px",
          boxShadow: "0px 10px 25px rgba(0,0,0,0.3)",
          width: "400px",
          textAlign: "center",
        }}
      >
        <h2 style={{ color: "#ff6f00", marginBottom: "20px" }}>
          🗺️ Welcome, {tourist?.name || "Traveler"}
        </h2>
        <p style={{ color: "#6b4d2b" }}>Plan your Kashi journey below</p>

        <input
          type="text"
          placeholder="Enter destination (e.g. Dashashwamedh Ghat)"
          value={destination}
          onChange={(e) => setDestination(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            margin: "10px 0",
            borderRadius: "10px",
            border: "1px solid #ccc",
          }}
        />
        <button
          onClick={handleAdd}
          style={{
            backgroundColor: "#ff6f00",
            color: "white",
            border: "none",
            padding: "10px",
            borderRadius: "10px",
            cursor: "pointer",
            width: "100%",
          }}
        >
          ➕ Add to Route
        </button>

        {places.length > 0 && (
          <div style={{ marginTop: "20px" }}>
            <h3 style={{ color: "#3b1f04" }}>🧭 Your Itinerary:</h3>
            <ul style={{ textAlign: "left", marginTop: "10px", color: "#4e342e" }}>
              {places.map((p, i) => (
                <li key={i}>• {p}</li>
              ))}
            </ul>

            <button
              onClick={handleStart}
              style={{
                marginTop: "20px",
                backgroundColor: "#2e7d32",
                color: "white",
                border: "none",
                padding: "10px 15px",
                borderRadius: "10px",
                cursor: "pointer",
                width: "100%",
              }}
            >
              🚀 Start My Route
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
